/* @lc app=leetcode id=1871 lang=kotlin */
class Solution { fun canReach(s: String, minJump: Int, maxJump: Int): Boolean = (s.last() == '0') && BooleanArray(s.length).also { dp -> dp[0] = true }.also { dp -> IntArray(1).also { count -> (1 until s.length).forEach { i -> dp.also { count[0] += (if (i >= minJump && dp[i - minJump]) 1 else 0) - (if (i > maxJump && dp[i - maxJump - 1]) 1 else 0) }[i] = s[i] == '0' && count[0] > 0 } } }[s.length - 1] }